package main

import (
	"fmt"
	"strings"
)

// genWireDTOByName lists resource types whose Go wire/replication DTO struct must be
// generated by this tool rather than by oapi-codegen. oapi-codegen only emits a Go struct
// for a schema that some HTTP operation references directly; these resources are used only
// for replication (events), so no operation references them and oapi-codegen skips them.
// Before this generator they were hand-written in internal/oapi/wire_<name>.go.
var genWireDTOByName = map[string]bool{
	"Node":    true,
	"Finding": true,
}

// wireDTO is the Go-struct view of a resource's wire DTO, derived from its resourceSchema.
type wireDTO struct {
	Name   string
	Fields []wireDTOField
}

type wireDTOField struct {
	GoName  string // Go field name, e.g. "NodeId"
	GoType  string // Go type, e.g. "openapi_types.UUID", "*string", "*[]string"
	JSONTag string // full struct tag contents, e.g. `json:"nodeId"` or `json:"url,omitempty"`
}

// buildWireDTOs returns the DTO structs to generate, in canonicalTypeOrder, for the schemas
// whose type name is in genWireDTOByName.
func buildWireDTOs(schemas []resourceSchema) []wireDTO {
	byName := make(map[string]resourceSchema, len(schemas))
	for _, s := range schemas {
		byName[s.Name] = s
	}
	var out []wireDTO
	emitted := map[string]bool{}
	for _, name := range canonicalTypeOrder {
		if !genWireDTOByName[name] {
			continue
		}
		rs, ok := byName[name]
		if !ok {
			panic(fmt.Sprintf("buildWireDTOs: %q is in genWireDTOByName but has no resource schema", name))
		}
		out = append(out, wireDTOFromSchema(rs))
		emitted[name] = true
	}
	// Every genWireDTO type must have been emitted above; a leftover means it is missing
	// from canonicalTypeOrder, which would silently drop its DTO. Fail loud instead.
	for name := range genWireDTOByName {
		if !emitted[name] {
			panic(fmt.Sprintf("buildWireDTOs: %q is in genWireDTOByName but missing from canonicalTypeOrder", name))
		}
	}
	return out
}

// wireDTOFromSchema maps a resourceSchema into the Go wire DTO struct description.
func wireDTOFromSchema(rs resourceSchema) wireDTO {
	required := make(map[string]bool, len(rs.Required))
	for _, r := range rs.Required {
		required[r] = true
	}
	d := wireDTO{Name: rs.Name}
	for _, p := range rs.Props {
		req := required[p.WireName]
		d.Fields = append(d.Fields, wireDTOField{
			GoName:  upperFirst(p.WireName),
			GoType:  wireDTOGoType(p, req),
			JSONTag: wireDTOJSONTag(p.WireName, req),
		})
	}
	return d
}

// wireDTOGoType returns the Go type for a wire DTO field. Optional (non-required) scalar and
// uuid fields become pointers; optional arrays become pointer-to-slice; required arrays are
// plain slices. This matches the hand-written wire_node.go / wire_finding.go exactly.
func wireDTOGoType(p schemaProp, required bool) string {
	if p.IsArray {
		elem := wireDTOArrayElemType(p)
		if required {
			return "[]" + elem
		}
		return "*[]" + elem
	}
	base := wireDTOScalarType(p)
	if required {
		return base
	}
	return "*" + base
}

// wireDTOArrayElemType returns the Go element type of an array property.
func wireDTOArrayElemType(p schemaProp) string {
	switch {
	case p.ItemsRef != "":
		return p.ItemsRef // e.g. "Annotation", "ResourceRef"
	case p.ItemsFormat == "uuid":
		return "openapi_types.UUID"
	default:
		return p.ItemsType // e.g. "string"
	}
}

// wireDTOScalarType returns the Go type for a non-array property.
func wireDTOScalarType(p schemaProp) string {
	if p.Format == "uuid" {
		return "openapi_types.UUID"
	}
	if p.Ref != "" {
		// A bare $ref scalar property maps to the referenced Go type.
		return p.Ref
	}
	switch p.Type {
	case "string":
		return "string"
	case "boolean":
		return "bool"
	case "integer":
		return "int"
	case "number":
		return "float64"
	default:
		// Enum properties carry an empty Type but are string-valued on the wire.
		return "string"
	}
}

// wireDTOJSONTag renders the struct tag, adding ,omitempty for optional fields.
func wireDTOJSONTag(wireName string, required bool) string {
	if required {
		return fmt.Sprintf("`json:%q`", wireName)
	}
	return fmt.Sprintf("`json:%q`", wireName+",omitempty")
}

// emitWireDTOFile renders the generated wire DTO file content.
func emitWireDTOFile(dtos []wireDTO) string {
	var b strings.Builder
	b.WriteString("// Code generated by tools/gen. DO NOT EDIT.\n\n")
	b.WriteString("package oapi\n\n")
	b.WriteString("import openapi_types \"github.com/oapi-codegen/runtime/types\"\n\n")
	for i, d := range dtos {
		if i > 0 {
			b.WriteString("\n")
		}
		fmt.Fprintf(&b, "// %s is the wire/replication DTO for %s resources. It is defined in the\n", d.Name, strings.ToLower(d.Name))
		b.WriteString("// OpenAPI spec but not generated by oapi-codegen because no HTTP operation uses it directly.\n")
		fmt.Fprintf(&b, "type %s struct {\n", d.Name)
		for _, f := range d.Fields {
			fmt.Fprintf(&b, "\t%s %s %s\n", f.GoName, f.GoType, f.JSONTag)
		}
		b.WriteString("}\n")
	}
	return b.String()
}
